      throw new WorktreeError(`could not fast-forward ${shownBranch(targetName)} to ${shownBranch(branch)}: ${options.noRebase ? "the branch is not a descendant of the target (merge without --no-rebase)" : "the target moved while merging; run merge again"}`);
    }
    notes.push(`Fast-forwarded ${shownBranch(targetName)}.`);
  }

  if (waiver !== undefined) {
    const reason = waiver;
    try {
      updateRegistry(repo.commonDir, (reg) => {
        reg.waivers = [...(reg.waivers ?? []), { branch, head: gateState.head, reason, recordedAt: new Date().toISOString() }].slice(-MAX_RECORDS);
      });
    } catch (err) {
      // The target has already advanced: report the merge, and say the audit record is missing.
      notes.push(`The waiver could not be recorded in the registry (${redactSecrets((err as Error).message).slice(0, 150)}).`);
    }
  }

  if (!options.noRemove) {
    // The merged work is on the target. Only ignored output (build caches) may still be in the worktree; it goes with
    // it. Anything else left (edits inside a submodule cannot be committed from here, for one) is never forced away.
    let left: ReturnType<typeof statusOf> | undefined; // undefined: the inspection itself failed
    let initialized: string[];
    let unpublished: string[];
    try {
      left = statusOf(source.path, { ignoreSubmodules: "none" });
      initialized = left.total > 0 ? [] : initializedSubmodules(source.path); // one `git submodule status` for both notes
      unpublished = unpublishedSubmodules(source.path, initialized);
    } catch (err) {
      // The merge is done; whatever stops the safety checks keeps the worktree rather than failing the report.
      left = undefined;
      initialized = [];
      unpublished = [];
      notes.push(`Could not inspect the worktree after the merge (${redactSecrets((err as Error).message).slice(0, 150)}).`);
    }
    if (unpublished.length > 0) {
      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: submodule ${unpublished.map((sub) => printable(redactSecrets(sub))).join(", ")} has a commit that is on no remote branch, and removing the worktree would delete its only copy. Push it from there, then run \`worktree remove\`. The merge itself is done.`);
    } else if (left === undefined) {
      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: it could not be inspected, so nothing was deleted. The merge itself is done.`);
    } else if (left.total > 0) {
      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: ${left.total} uncommitted change(s) remain that the merge could not carry (check \`git status\` there, submodules included). Nothing was deleted.`);
    } else if (initialized.length > 0) {
      notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: submodule ${initialized.map((sub) => printable(redactSecrets(sub))).join(", ")} is initialized here; removing it requires \`worktree remove --force\` after verifying submodule state. The merge itself is done.`);
    } else {
      try {
        notes.push(removeOne({ ...ctx, cwd: targetEntry.path }, source.path, { discardIgnored: true, target: targetName }));
      } catch (err) {
        notes.push(`Kept the worktree ${shownPath(ctx.home, source.path)}: removal failed (${redactSecrets((err as Error).message).slice(0, 150)}). The merge itself is done.`);
      }
    }
  }

  const removedPath = !fs.existsSync(source.path) ? source.path : undefined;
  return { success: true, output: notes.join("\n"), data: { branch, target: targetName, targetPath: targetEntry.path, ...(removedPath ? { removedPath } : {}) } };
}

